import csv
import io

def most_common_csv_words(csv_text, delimiter):
    # Dicts preserve insertion order, so each word's position reflects
    # its first appearance in the text.
    counts = {}
    reader = csv.reader(io.StringIO(csv_text), delimiter=delimiter)
    for row in reader:
        for cell in row:
            word = cell.strip()
            if word:  # skip empty cells
                counts[word] = counts.get(word, 0) + 1

    # sorted() is stable, so words with equal counts keep their first-occurrence order.
    return sorted(counts.items(), key=lambda item: -item[1])


if __name__ == "__main__":
    print(most_common_csv_words("apple,banana\nbanana,cherry\nbanana,apple", ","))
    # [('banana', 3), ('apple', 2), ('cherry', 1)]
```

The function uses Python's `csv` module so that quoted cells and multiline records are parsed correctly. It counts each non-empty cell (after stripping surrounding whitespace), and the stable sort on negated counts keeps ties in the order the words first appeared.

