import csv
from io import StringIO


def top_selling_product(csv_text):
    """Return the product with the highest total quantity sold.

    The first line of csv_text is treated as a header. Each data row has a
    product name and an integer quantity. A product may appear on several rows,
    and its quantities are summed. Ties are broken by whichever tied product
    appears first in the data.

    Raises ValueError if there are no data rows or a quantity is not a valid integer.
    """
    reader = csv.reader(StringIO(csv_text))

    try:
        next(reader)  # skip header
    except StopIteration:
        raise ValueError("CSV contains no header or data rows")

    totals = {}
    for row in reader:
        # Skip blank lines
        if not row or all(not cell.strip() for cell in row):
            continue

        if len(row) < 2:
            raise ValueError(f"malformed row: {row!r}")

        product = row[0].strip()
        raw_quantity = row[1].strip()
        try:
            quantity = int(raw_quantity)
        except ValueError:
            raise ValueError(f"invalid quantity: {raw_quantity!r}") from None

        totals[product] = totals.get(product, 0) + quantity

    if not totals:
        raise ValueError("CSV contains no data rows")

    return max(totals, key=totals.get)


if __name__ == "__main__":
    print(top_selling_product("product,quantity\nApple,5\nPear,3\nApple,2\n"))  # Apple
