import csv
from io import StringIO


def top_selling_product(csv_text):
    """Return the product with the highest total quantity sold.

    csv_text: contents of a sales CSV with a header line and columns
              'product' and 'quantity'.
    Raises ValueError if there are no data rows, if a quantity is not a
    valid integer, or if the required columns are missing.
    """
    reader = csv.reader(StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV has no header line")

    normalized = [h.strip().lower() for h in header]
    try:
        product_idx = normalized.index("product")
        quantity_idx = normalized.index("quantity")
    except ValueError:
        raise ValueError("CSV header must contain 'product' and 'quantity' columns")

    totals = {}  # dict preserves first-appearance order, used for tie-breaking
    for row in reader:
        # Skip completely blank lines
        if not row or all(not cell.strip() for cell in row):
            continue

        if max(product_idx, quantity_idx) >= len(row):
            raise ValueError(f"row has too few columns: {row!r}")

        product = row[product_idx].strip()
        raw_qty = row[quantity_idx].strip()
        try:
            quantity = int(raw_qty)
        except ValueError:
            raise ValueError(f"invalid quantity {raw_qty!r} for product {product!r}") from None

        totals[product] = totals.get(product, 0) + quantity

    if not totals:
        raise ValueError("CSV has no data rows")

    return max(totals, key=totals.get)


if __name__ == "__main__":
    print(top_selling_product("product,quantity\nApple,5\nPear,3\nApple,2\n"))  # Apple
```

The function reads the header to locate the `product` and `quantity` columns, then sums quantities per product. It returns the product with the largest total. If two products tie, it returns the one that appears first in the file. It raises `ValueError` when there are no data rows, when a quantity isn't an integer, or when a row is missing a column.

