import json
from collections import Counter


def count_urls_in_json(json_str, top_n=10):
    """
    Count URL string values in a JSON document, including those nested in
    objects and arrays, and return the `top_n` most frequent ones.

    A string value is treated as a URL if it starts with "http://",
    "https://" or "www.". Keys are not counted, only values.

    Returns a dict mapping each URL to its count, ordered from most to
    least frequent. Ties keep the order in which the URLs first appear.

    Raises ValueError if json_str is not valid JSON.
    """
    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError) as e:
        raise ValueError(f"Invalid JSON: {e}") from e

    prefixes = ("http://", "https://", "www.")
    counts = Counter()

    def collect(value):
        if isinstance(value, dict):
            for v in value.values():
                collect(v)
        elif isinstance(value, list):
            for item in value:
                collect(item)
        elif isinstance(value, str) and value.startswith(prefixes):
            counts[value] += 1

    collect(data)

    if top_n is None:
        return dict(counts.most_common())
    return dict(counts.most_common(max(top_n, 0)))


if __name__ == "__main__":
    example = (
        '{"name": "John", "social": {"twitter": "https://twitter.com/john", '
        '"linkedin": "https://linkedin.com/in/john"}, '
        '"website": "https://linkedin.com/in/john"}'
    )
    print(count_urls_in_json(example))
    # {'https://linkedin.com/in/john': 2, 'https://twitter.com/john': 1}
```

The function parses the string with `json.loads` and raises `ValueError` if parsing fails. It then walks every value recursively, descending into nested objects and arrays, and counts strings that start with one of the three prefixes. Keys are never counted. Finally, `Counter.most_common` selects the `top_n` most frequent URLs.

The prefix check is case-sensitive, as the spec describes. If you want `HTTP://EXAMPLE.COM` to count too, lowercase the value before the `startswith` check.

```python
import json
from collections import Counter

URL_PREFIXES = ("http://", "https://", "www.")


def count_urls_in_json(json_str, top_n=10):
    """
    Count URL string values in a JSON document, including nested objects and arrays.

    A string value counts as a URL if it starts with "http://", "https://", or "www.".
    Keys are not counted, only values.

    Returns a dict mapping the `top_n` most frequent URLs to their counts.
    Raises ValueError if `json_str` is not valid JSON.
    """
    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError) as e:
        raise ValueError(f"Invalid JSON: {e}") from e

    counts = Counter()

    def walk(node):
        if isinstance(node, dict):
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for item in node:
                walk(item)
        elif isinstance(node, str) and node.startswith(URL_PREFIXES):
            counts[node] += 1

    walk(data)
    return dict(counts.most_common(top_n))


if __name__ == "__main__":
    example = (
        '{"name": "John", "social": {"twitter": "https://twitter.com/john", '
        '"linkedin": "https://linkedin.com/in/john"}, '
        '"website": "https://linkedin.com/in/john"}'
    )
    print(count_urls_in_json(example))
    # {'https://linkedin.com/in/john': 2, 'https://twitter.com/john': 1}
```

Notes on the implementation:

- **Nested data:** The recursive `walk` function visits every value in nested objects and arrays. Only values are checked, not keys.
- **Matching:** The prefix check is case-sensitive, as described in the spec. If you want `HTTP://EXAMPLE.COM` to count too, lowercase the string before the `startswith` check.
- **Ties:** `Counter.most_common` breaks ties by first occurrence in the document.
- **Invalid input:** `json.loads` failures (and non-string input) are re-raised as `ValueError`.

