def error_times_and_average(logs):
    error_times = []

    for line in logs:
        parts = line.split()
        # Expected format: "YYYY-MM-DD HH:MM:SS LEVEL: message"
        if len(parts) < 3 or parts[2].rstrip(':') != 'ERROR':
            continue

        hour, minute = parts[1].split(':')[:2]
        error_times.append((int(hour), int(minute)))

    if not error_times:
        return [], (0, 0)

    total_minutes = sum(h * 60 + m for h, m in error_times)
    avg_minutes = total_minutes // len(error_times)  # rounded down

    return error_times, (avg_minutes // 60, avg_minutes % 60)


