        # Wrap in double quotes, doubling any embedded quotes.
        return '"' + str(s).replace('"', '""') + '"'

    def field(v):
        # Numbers (excluding bools) are left bare; everything else is quoted.
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return str(v)
        return quote(v)

    if not columns:
        return ""

    names = list(columns.keys())
    cols = [list(columns[name]) for name in names]
    n_rows = len(cols[0])

    lines = [",".join(quote(name) for name in names)]
