    """Convert a dict of equal-length column lists into CSV text.

    - The header row contains the column names, always double-quoted.
    - Each record is one row, with columns in the dict's order.
    - Numbers (int or float, excluding bool) are written unquoted.
    - All other values are converted with str() and double-quoted.
    - Embedded double quotes are doubled.
    - Every line, including the last, ends with '\\n'.
    """
    def quote(text):
        return '"' + text.replace('"', '""') + '"'

    def format_value(value):
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return str(value)
        return quote(str(value))

    names = list(columns.keys())
    if not names:
        return ""

    lines = [",".join(quote(str(name)) for name in names)]

    num_rows = len(columns[names[0]])
    for i in range(num_rows):
        lines.append(",".join(format_value(columns[name][i]) for name in names))

    return "".join(line + "\n" for line in lines)


