import ast
import json
from collections import Counter


def count_record_keys(json_text):
    """
    Count how many records each top-level key appears in.

    `json_text` is a JSON string holding a list. Each item is either:
      - a JSON object (dict), or
      - a string containing a dictionary written as text (JSON or Python literal).

    String items that do not hold a dictionary are skipped.
    """
    records = json.loads(json_text)
    if not isinstance(records, list):
        return {}

    counts = Counter()

    for item in records:
        if isinstance(item, dict):
            record = item
        elif isinstance(item, str):
            record = None
            try:
                record = json.loads(item)
            except (ValueError, TypeError):
                try:
                    record = ast.literal_eval(item)
                except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
                    record = None
            if not isinstance(record, dict):
                continue
        else:
            continue

        counts.update(record.keys())

    return dict(counts)


