import json
from collections import Counter


def count_key_values(json_documents, key):
    """
    Count how often each value of `key` appears across JSON object strings.

    Documents that are not JSON objects or do not contain `key` are ignored.
    Unhashable values (lists, dicts) are counted by their canonical JSON form.
    """
    counts = Counter()
    for doc in json_documents:
        obj = json.loads(doc)
        if not isinstance(obj, dict) or key not in obj:
            continue
        value = obj[key]
        try:
            hash(value)
        except TypeError:
            value = json.dumps(value, sort_keys=True)
        counts[value] += 1
    return dict(counts)


