import json
from collections import Counter

def count_key_values(json_documents, key):
    """
    Count how many JSON documents have each value for the given key.

    Documents that don't contain the key (or aren't JSON objects) are ignored.
    """
    counts = Counter()
    for doc in json_documents:
        obj = json.loads(doc)
        if isinstance(obj, dict) and key in obj:
            value = obj[key]
            try:
                counts[value] += 1
            except TypeError:
                # Lists and dicts are unhashable; use a canonical JSON string as the dict key.
                counts[json.dumps(value, sort_keys=True)] += 1
    return dict(counts)


if __name__ == "__main__":
    docs = [
        '{"product": "apple", "quantity": 5}',
        '{"product": "banana", "quantity": 3}',
        '{"product": "apple"}',
    ]
    print(count_key_values(docs, 'product'))  # {'apple': 2, 'banana': 1}
```

Each document contributes at most one count, since a JSON object has only one value per key. The `TypeError` fallback only matters when the value is a list or object, which can't be a dict key in Python; in that case the value is stored as its canonical JSON string.

