import ast


def parse_dict_lines(texts):
    """
    Parse a list of file contents, where each line of each file is a Python
    dictionary literal. Returns the dictionaries in file order, then line order.

    Raises ValueError if any line is not a valid dictionary literal.
    """
    result = []
    for file_index, text in enumerate(texts):
        for line_index, line in enumerate(text.splitlines(), start=1):
            try:
                value = ast.literal_eval(line.strip())
            except (SyntaxError, ValueError, TypeError, MemoryError, RecursionError) as exc:
                raise ValueError(
                    f"file {file_index}, line {line_index}: not a valid literal "
                    f"({exc!r}): {line!r}"
                ) from exc

            if not isinstance(value, dict):
                raise ValueError(
                    f"file {file_index}, line {line_index}: not a dictionary literal: {line!r}"
                )
            result.append(value)
    return result


if __name__ == "__main__":
    print(parse_dict_lines(["{'a': 1}\n{'b': 'x'}", "{'c': [1, 2]}"]))
    # [{'a': 1}, {'b': 'x'}, {'c': [1, 2]}]
```

This uses `ast.literal_eval` rather than `eval`, so it only accepts Python literals and cannot execute arbitrary code. Each line is stripped of surrounding whitespace before parsing. Blank lines are treated as invalid, since they are not dictionary literals; if you want trailing blank lines in a file to be ignored, skip lines where `line.strip()` is empty.

