```python
import ast

def parse_dict_lines(texts):
    """
    Parse a list of file contents, where each line of each file is a Python
    dictionary literal. Returns the dictionaries in file order, then line order.

    Blank (or whitespace-only) lines are skipped. Any non-blank line that is
    not a valid dictionary literal raises ValueError.
    """
    result = []
    for file_index, text in enumerate(texts):
        for line_no, line in enumerate(text.splitlines(), start=1):
            stripped = line.strip()
            if not stripped:
                continue
            try:
                value = ast.literal_eval(stripped)
            except (ValueError, TypeError, SyntaxError, MemoryError, RecursionError) as exc:
                raise ValueError(
                    f"File {file_index}, line {line_no}: not a valid literal: {line!r}"
                ) from exc
            if not isinstance(value, dict):
                raise ValueError(
                    f"File {file_index}, line {line_no}: not a dictionary literal: {line!r}"
                )
            result.append(value)
    return result


if __name__ == "__main__":
    print(parse_dict_lines(["{'a': 1}\n{'b': 'x'}", "{'c': [1, 2]}"]))
    # [{'a': 1}, {'b': 'x'}, {'c': [1, 2]}]
```

The function uses `ast.literal_eval`, so it only accepts Python literals (strings, numbers, lists, tuples, dicts, sets, `None`, booleans, and so on) and never executes code. A line like `{'a': x}` or `[1, 2]` is rejected: the first because `x` is a name, not a literal, and the second because the result isn't a dict.

