def wrap_each_line(text, width):
    result = []
    for line in text.split('\n'):
        words = line.split()
        if not words:
            # Preserve blank lines from the original text
            result.append('')
            continue

        current = words[0]
        for word in words[1:]:
            # Add the next word to the current line if it fits
            if len(current) + 1 + len(word) <= width:
                current += ' ' + word
            else:
                result.append(current)
                current = word  # A long word stays whole on its own line
        result.append(current)

    return '\n'.join(result)


print(repr(wrap_each_line('Hello world\nThis is a test string\nHappy coding!', 10)))
