```python
import base64
import binascii
import json
import unicodedata


def decode_base64_json_values(json_text):
    """
    Parse a JSON object string whose values are base64-encoded UTF-8 strings.
    Return a dict with the same keys, each value decoded and normalized to NFC.

    Raises ValueError if the input is not a valid JSON object, if a value is
    not a string, if a value is not valid base64, or if the decoded bytes are
    not valid UTF-8.
    """
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON top-level value must be an object")

    result = {}
    for key, value in data.items():
        if not isinstance(value, str):
            raise ValueError(f"Value for key {key!r} is not a string")

        try:
            raw = base64.b64decode(value, validate=True)
        except (binascii.Error, ValueError) as exc:
            raise ValueError(f"Invalid base64 for key {key!r}: {exc}") from exc

        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError(f"Decoded value for key {key!r} is not valid UTF-8") from exc

        result[key] = unicodedata.normalize("NFC", text)

    return result


if __name__ == "__main__":
    print(decode_base64_json_values('{"key1": "SGVsbG8gV29ybGQ=", "key2": "Y2Fmw6k="}'))
    # {'key1': 'Hello World', 'key2': 'café'}
```

Notes on the implementation:

- `json.loads` errors are converted to `ValueError`. `JSONDecodeError` is already a `ValueError` subclass, but wrapping it gives a consistent message.
- `base64.b64decode(..., validate=True)` rejects characters outside the base64 alphabet. Without it, Python silently discards them.
- Invalid UTF-8 in the decoded bytes is reported as a `ValueError` as well.
- Non-string values and a non-object top level are rejected, since the spec requires a JSON object of base64 strings.
- `unicodedata.normalize("NFC", ...)` is applied after decoding, so `"café"` written with a combining accent comes out in the same composed form as the precomposed version.

```python
import base64
import binascii
import json
import unicodedata


def decode_base64_json_values(json_text):
    """
    Parse a JSON object whose values are base64-encoded UTF-8 strings.

    Returns a dict with the same keys, where each value is the decoded text
    normalized to Unicode NFC form.

    Raises ValueError if the input is not a valid JSON object, if a value is
    not a string, if a value is not valid base64, or if the decoded bytes
    are not valid UTF-8.
    """
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as e:
        raise ValueError(f"Invalid JSON: {e}") from e

    if not isinstance(data, dict):
        raise ValueError("JSON text must represent an object")

    result = {}
    for key, value in data.items():
        if not isinstance(value, str):
            raise ValueError(f"Value for key {key!r} is not a string")

        try:
            raw = base64.b64decode(value, validate=True)
        except (binascii.Error, ValueError) as e:
            raise ValueError(f"Invalid base64 for key {key!r}: {e}") from e

        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as e:
            raise ValueError(f"Decoded value for key {key!r} is not valid UTF-8: {e}") from e

        result[key] = unicodedata.normalize("NFC", text)

    return result


if __name__ == "__main__":
    print(decode_base64_json_values('{"key1": "SGVsbG8gV29ybGQ=", "key2": "Y2Fmw6k="}'))
    # {'key1': 'Hello World', 'key2': 'café'}
```

